// services/reportService.js — reads and updates reports in Firestore.
// Reports are stored in the SAME 'incidents' collection that the existing
// user application writes to — the admin app does NOT create a new collection.

import {
  collection,
  getDocs,
  getDoc,
  doc,
  updateDoc,
  query,
  orderBy,
  serverTimestamp,
} from 'firebase/firestore'
import { db } from '../firebase/firebase'

// A report document looks like this (kept in sync with the user app):
// {
//   id: <auto-generated firestore id>,
//   title: "Bags dumped near riverbank",
//   wasteType: "Household waste",          // optional
//   description: "...",
//   location: { lat, lng },
//   evidenceImages: ["https://..."],
//   status: 'pending' | 'verified' | 'resolved' | 'rejected',
//   reporterName: "Maria Santos",
//   reportedBy: <user uid>,
//   createdAt: <Firebase Timestamp>,
//   updatedAt: <Firebase Timestamp>
// }

const collectionRef = collection(db, 'incidents')

// Fetch every report, newest first.
export async function getReports() {
  const q = query(collectionRef, orderBy('createdAt', 'desc'))
  const snap = await getDocs(q)
  return snap.docs.map((d) => ({ id: d.id, ...d.data() }))
}

// Fetch a single report by Firestore document id.
export async function getReport(id) {
  const snap = await getDoc(doc(db, 'incidents', id))
  return snap.exists() ? { id: snap.id, ...snap.data() } : null
}

// Update a report's status (and optional notes).
export async function updateReportStatus(id, { status, notes }) {
  await updateDoc(doc(db, 'incidents', id), {
    status,
    ...(notes !== undefined ? { notes } : {}),
    updatedAt: serverTimestamp(),
  })
}